use anyhow :: { Context , Result } ; use serde :: { Deserialize , Serialize } ; use std :: fs ; use std :: path :: Path ; use super :: * ; use serde_json :: json ; use tempfile :: NamedTempFile ; # [doc = " Convert value to integer, handling floats and integers"] fn as_int (value : serde_json :: Value) -> i64 { match value { serde_json :: Value :: Number (n) => { if let Some (i) = n . as_i64 () { i } else if let Some (f) = n . as_f64 () { f as i64 } else { 0 } } _ => 0 , } }